/**
 * Hebrew text of the Bible books, generated by scripts/fetch-books.mjs into public/books/.
 * - index.json is small and precached by the service worker,
 * - every book is a separate JSON file, downloaded on demand and kept in the Cache API
 *   (so it works offline; "downloaded" simply means "present in that cache").
 */

export interface BookMeta {
  id: string
  name: string
  polishName: string
  hebrewName: string
  file: string
  /** Number of verses in each chapter. */
  verses: number[]
  bytes: number
}

export interface BookIndex {
  source: { name: string; url: string; note: string }
  books: BookMeta[]
}

interface BookData {
  id: string
  chapters: string[][]
}

export interface Passage {
  book: BookMeta
  chapter: number
  from: number
  to: number
  text: string
  /** Human-readable reference, e.g. "Księga Rodzaju 1:1–3". */
  reference: string
}

export const CACHE_NAME = 'bereszit-books'
export const MAX_VERSES = 5

const base = (): string => import.meta.env.BASE_URL

const urlOf = (path: string): string => new URL(`${base()}books/${path}`, globalThis.location.href).toString()

const openCache = async (): Promise<Cache | undefined> => {
  try {
    return typeof caches === 'undefined' ? undefined : await caches.open(CACHE_NAME)
  } catch {
    return undefined
  }
}

let indexPromise: Promise<BookIndex> | null = null

export const loadIndex = (): Promise<BookIndex> => {
  indexPromise ??= fetch(urlOf('index.json'))
    .then((res) => {
      if (!res.ok) throw new Error(`index.json: HTTP ${res.status}`)
      return res.json() as Promise<BookIndex>
    })
    .catch((error) => {
      indexPromise = null // allow a retry
      throw error
    })
  return indexPromise
}

const memory = new Map<string, BookData>()

/** Returns the book from the cache, or downloads and caches it. */
export const loadBook = async (book: BookMeta): Promise<BookData> => {
  const known = memory.get(book.id)
  if (known) return known

  const url = urlOf(book.file)
  const cache = await openCache()
  let response = await cache?.match(url)
  if (!response) {
    response = await fetch(url)
    if (!response.ok) throw new Error(`${book.file}: HTTP ${response.status}`)
    try {
      await cache?.put(url, response.clone())
    } catch {
      /* quota exceeded or storage blocked: the book still works for this session */
    }
  }
  const data = (await response.json()) as BookData
  memory.set(book.id, data)
  return data
}

/** Ids of the books currently stored for offline use. */
export const downloadedBookIds = async (index: BookIndex): Promise<Set<string>> => {
  const cache = await openCache()
  const found = new Set<string>()
  if (!cache) return found
  for (const book of index.books) {
    if (await cache.match(urlOf(book.file))) found.add(book.id)
  }
  return found
}

export const removeBook = async (book: BookMeta): Promise<void> => {
  memory.delete(book.id)
  const cache = await openCache()
  await cache?.delete(urlOf(book.file))
}

/** Asks the browser not to evict the stored books (best effort, may be refused). */
export const requestPersistence = async (): Promise<boolean> => {
  try {
    return (await navigator.storage?.persist?.()) ?? false
  } catch {
    return false
  }
}

export const formatReference = (book: BookMeta, chapter: number, from: number, to: number): string =>
  `${book.polishName} ${chapter}:${from}${to > from ? `–${to}` : ''}`

/** `count` consecutive verses of one chapter, starting at `from` (clipped to the end of the chapter). */
export const getPassage = async (
  book: BookMeta,
  chapter: number,
  from: number,
  count: number,
): Promise<Passage> => {
  const data = await loadBook(book)
  const verses = data.chapters[chapter - 1]
  if (!verses) throw new Error(`No chapter ${chapter} in ${book.id}`)
  const start = Math.min(Math.max(from, 1), verses.length)
  const end = Math.min(start + count - 1, verses.length)
  return {
    book,
    chapter,
    from: start,
    to: end,
    text: verses.slice(start - 1, end).join(' '),
    reference: formatReference(book, chapter, start, end),
  }
}

/** Where a random pick lands: every verse of the index is equally likely. */
export const pickRandomPlace = (
  index: BookIndex,
  count: number,
  rng: () => number = Math.random,
): { book: BookMeta; chapter: number; from: number } => {
  const total = index.books.reduce((sum, b) => sum + b.verses.reduce((a, n) => a + n, 0), 0)
  let target = Math.floor(rng() * total)
  for (const book of index.books) {
    for (let c = 0; c < book.verses.length; c++) {
      const inChapter = book.verses[c]!
      if (target < inChapter) {
        // Move the start back so a pick near the end of a chapter still gives `count` verses.
        const from = Math.max(1, Math.min(target + 1, inChapter - count + 1))
        return { book, chapter: c + 1, from }
      }
      target -= inChapter
    }
  }
  throw new Error('Empty book index')
}

export const randomPassage = async (
  index: BookIndex,
  count: number,
  rng: () => number = Math.random,
): Promise<Passage> => {
  const place = pickRandomPlace(index, count, rng)
  return getPassage(place.book, place.chapter, place.from, count)
}

/** "1 werset", "2 wersety", "5 wersetów" */
export const versesLabel = (n: number): string =>
  `${n} ${n === 1 ? 'werset' : n >= 2 && n <= 4 ? 'wersety' : 'wersetów'}`
